```go
package main

import "fmt"

func run(value int, hook func(int)) {
    if hook != nil {
        hook(value)
    }
}

func main() {
    run(7, func(value int) { fmt.Println("value", value) })
    run(8, nil)
}
```
Only `value 7` is printed. The nil check expresses an optional hook without trying to compare one implementation with another.

```go
package main

import "fmt"

type LogFunc func(string)

func worker(log LogFunc) func() {
    if log == nil {
        log = func(string) {}
    }
    return func() { log("finished") }
}

func main() {
    worker(nil)()
    worker(func(message string) { fmt.Println(message) })()
}
```
The first worker completes silently and the second prints `finished`. Both call sites use the same non-nil invariant after construction.

```go
package main

import "fmt"

type Registry struct {
    next int
    handlers map[int]func(string)
}

func (r *Registry) Subscribe(handler func(string)) func() {
    id := r.next
    r.next++
    r.handlers[id] = handler
    return func() { delete(r.handlers, id) }
}

func main() {
    r := Registry{handlers: map[int]func(string){}}
    off := r.Subscribe(func(s string) { fmt.Println(s) })
    r.handlers[0]("ready")
    off()
    off()
    fmt.Println(len(r.handlers))
}
```
The program prints `ready` and `0`. Deleting the same map key twice is safe, so this small unsubscribe operation is idempotent. A concurrent registry would also protect the map.

```go
package main

import "fmt"

type Handler interface { Handle(string) }

type HandlerFunc func(string)

func (f HandlerFunc) Handle(value string) { f(value) }

func dispatch(h Handler, value string) { h.Handle(value) }

func main() {
    dispatch(HandlerFunc(func(value string) {
        fmt.Println("handled", value)
    }), "job-7")
}
```
The output is `handled job-7`. `HandlerFunc` keeps the concise closure while its `Handle` method satisfies the interface.
